import{_ as l,C as s,o as i,c as o,a3 as t,E as a}from"./chunks/framework.DwOFkeYk.js";const b=JSON.parse('{"title":"Séance 4 — Essayer et comparer des outils","description":"","frontmatter":{"title":"Séance 4 — Essayer et comparer des outils","aside":false},"headers":[],"relativePath":"modules/01-faisabilite/04-essayer-et-comparer.md","filePath":"modules/01-faisabilite/04-essayer-et-comparer.md"}'),u={name:"modules/01-faisabilite/04-essayer-et-comparer.md"};function d(c,e,p,g,m,f){const n=s("ConstatOuRecommandation"),r=s("CoutTroisAns");return i(),o("div",null,[e[0]||(e[0]=t('<h1 id="seance-4-—-essayer-et-comparer-des-outils" tabindex="-1">Séance 4 — Essayer et comparer des outils <a class="header-anchor" href="#seance-4-—-essayer-et-comparer-des-outils" aria-label="Permalink to &quot;Séance 4 — Essayer et comparer des outils&quot;">​</a></h1><h2 id="objectifs" tabindex="-1">Objectifs <a class="header-anchor" href="#objectifs" aria-label="Permalink to &quot;Objectifs&quot;">​</a></h2><ul><li>Faire les essais prévus au Lab 03 et en <strong>documenter les résultats</strong> : réussi, échoué ou non vérifiable, avec une mesure et une preuve.</li><li>Écrire un <strong>constat appuyé</strong>, sans jugement vague et sans recommandation.</li><li>Comparer des outils sur les critères de l&#39;évaluation 1 : ce qu&#39;ils font, le <strong>coût sur trois ans</strong>, le <strong>temps pour apprendre</strong>, la <strong>facilité d&#39;en sortir</strong> et les <strong>signes de pérennité</strong> (ces trois derniers se complètent à la maison).</li></ul><h2 id="deroulement-de-la-seance" tabindex="-1">Déroulement de la séance <a class="header-anchor" href="#deroulement-de-la-seance" aria-label="Permalink to &quot;Déroulement de la séance&quot;">​</a></h2><p>La séance se fait en deux temps : <strong>toute la matière d&#39;abord</strong>, en grand groupe, puis <strong>le reste de la soirée pour le Lab 04</strong>, en équipe. L&#39;enseignant reste disponible dans la réunion du cours pendant le lab.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Heure</th><th style="text-align:left;">Activité</th></tr></thead><tbody><tr><td style="text-align:left;">18 h 30</td><td style="text-align:left;">Retour sur les plans d&#39;essai du Lab 03</td></tr><tr><td style="text-align:left;">18 h 40</td><td style="text-align:left;">Documenter un essai</td></tr><tr><td style="text-align:left;">18 h 55</td><td style="text-align:left;">Activité 1 — Constat, affirmation non appuyée ou recommandation ?</td></tr><tr><td style="text-align:left;">19 h 20</td><td style="text-align:left;">Comparer sans recommander : les familles de solutions et les critères du tableau</td></tr><tr><td style="text-align:left;">19 h 35</td><td style="text-align:left;">Les consignes du Lab 04 et ce qu&#39;il y a à faire à la maison</td></tr><tr><td style="text-align:left;">19 h 45</td><td style="text-align:left;">Pause</td></tr><tr><td style="text-align:left;">20 h 00</td><td style="text-align:left;"><a href="./../../labs/lab04-essais">Lab 04 — Les essais</a>, en équipe, jusqu&#39;à la fin de la soirée</td></tr></tbody></table><p>Le <strong>retour en grand groupe</strong> sur les cinq questions aura lieu <strong>au début de la séance 5</strong>.</p><hr><h2 id="retour-sur-le-lab-03" tabindex="-1">Retour sur le Lab 03 <a class="header-anchor" href="#retour-sur-le-lab-03" aria-label="Permalink to &quot;Retour sur le Lab 03&quot;">​</a></h2><p>Ce soir, vous passez de la lecture à l&#39;essai. Un plan d&#39;essai faible se voit tout de suite : on improvise, chaque outil est essayé différemment, et à la fin on ne peut rien comparer.</p><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Ce qui revient le plus souvent dans les plans</strong><br><ul class="list-disc pl-5"><li><strong>Des critères qui ne se mesurent pas.</strong> « Réussi si c&#39;est facile » ou « si ça marche bien ». Remplacez l&#39;adjectif par un chiffre ou par un fait observable : un temps, un nombre de clics, oui ou non.</li><li><strong>Des scénarios sans données.</strong> « Tester la réservation » ne dit pas quoi réserver, pour combien de personnes, sur quel appareil.</li><li><strong>Des essais différents d&#39;un outil à l&#39;autre.</strong> La règle ne change pas : les mêmes essais, dans le même ordre, sur chaque outil.</li></ul></div><p><strong>Le test des deux observateurs :</strong> deux personnes regardent le même essai, chacune de son côté. Si elles peuvent arriver à un verdict différent, le critère n&#39;est pas assez précis. Au début du lab, prenez cinq minutes pour corriger vos critères <strong>avant</strong> de commencer les essais.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Critère faible</th><th style="text-align:left;">Critère mesurable</th></tr></thead><tbody><tr><td style="text-align:left;">Réussi si la réservation est rapide</td><td style="text-align:left;">Réussi si la réservation de 5 places prend moins de 3 minutes sur téléphone, sans aide</td></tr><tr><td style="text-align:left;">Réussi si l&#39;outil fonctionne hors ligne</td><td style="text-align:left;">Réussi si, en mode avion, la liste des participants du jour et leurs allergies s&#39;affichent</td></tr><tr><td style="text-align:left;">Réussi si Mélanie peut s&#39;en servir</td><td style="text-align:left;">Réussi si le membre qui n&#39;a jamais vu l&#39;outil change un prix en moins de 5 minutes, sans ouvrir l&#39;aide</td></tr><tr><td style="text-align:left;">Réussi si la vidéo ne ralentit pas le site</td><td style="text-align:left;">Réussi si le LCP mobile de la page reste sous 2,5 secondes dans PageSpeed Insights</td></tr></tbody></table><hr><h2 id="documenter-un-essai" tabindex="-1">Documenter un essai <a class="header-anchor" href="#documenter-un-essai" aria-label="Permalink to &quot;Documenter un essai&quot;">​</a></h2><p>Un essai qui n&#39;est pas noté n&#39;a pas eu lieu. Dans le rapport, chaque résultat doit pouvoir être <strong>retrouvé</strong> : quel outil, quel jour, quelle mesure, quelle capture.</p><h3 id="trois-resultats-possibles" tabindex="-1">Trois résultats possibles <a class="header-anchor" href="#trois-resultats-possibles" aria-label="Permalink to &quot;Trois résultats possibles&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Résultat</th><th style="text-align:left;">Quand l&#39;utiliser</th><th style="text-align:left;">Exemple</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Réussi</strong> ✓</td><td style="text-align:left;">Le critère décidé d&#39;avance est atteint.</td><td style="text-align:left;">La réservation de 5 places a pris 2 min 40 s. Il reste bien 3 places.</td></tr><tr><td style="text-align:left;"><strong>Échoué</strong> ✗</td><td style="text-align:left;">L&#39;outil permet la manipulation, mais le critère n&#39;est pas atteint. Ou l&#39;outil ne le permet pas du tout.</td><td style="text-align:left;">En mode avion, l&#39;application affiche « Aucune connexion » et aucune liste.</td></tr><tr><td style="text-align:left;"><strong>Non vérifiable</strong> ?</td><td style="text-align:left;">L&#39;essai ne permet pas de savoir : fonction bloquée pendant l&#39;essai, besoin d&#39;un vrai compte Viator, d&#39;un vrai paiement…</td><td style="text-align:left;">La connexion à Viator exige un compte Viator d&#39;entreprise.</td></tr></tbody></table><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>« Non vérifiable » n&#39;est pas un échec de votre part</strong><br> C&#39;est un résultat honnête, à condition d&#39;écrire <strong>pourquoi</strong> et <strong>ce qui permettrait de vérifier</strong> (une démonstration du vendeur, une question au support, un compte réel). Ces points deviennent les problèmes à prévoir et les questions de la section 7 du rapport. Ne transformez jamais un « non vérifiable » en « réussi » parce que la documentation le promet. </div><h3 id="ce-qu-on-note-pour-chaque-essai" tabindex="-1">Ce qu&#39;on note pour chaque essai <a class="header-anchor" href="#ce-qu-on-note-pour-chaque-essai" aria-label="Permalink to &quot;Ce qu&#39;on note pour chaque essai&quot;">​</a></h3><ul><li><strong>La mesure brute :</strong> « 2 min 40 s », « 14 clics », « 3,8 Mo », « score de 62 ». Pas « assez vite ».</li><li><strong>Le résultat :</strong> réussi, échoué ou non vérifiable.</li><li><strong>Ce qu&#39;on a observé :</strong> un message d&#39;erreur, une étape inattendue, une fonction introuvable, une aide demandée.</li><li><strong>La preuve :</strong> au moins une capture d&#39;écran, nommée pour qu&#39;on la retrouve : <code>Q1-Checkfront-E3-01.png</code> (question, outil, essai, numéro).</li><li><strong>Le contexte, une seule fois par outil :</strong> la date, le forfait d&#39;essai utilisé, l&#39;appareil et le navigateur.</li></ul><h3 id="les-regles-pendant-l-essai" tabindex="-1">Les règles pendant l&#39;essai <a class="header-anchor" href="#les-regles-pendant-l-essai" aria-label="Permalink to &quot;Les règles pendant l&#39;essai&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Règle</th><th style="text-align:left;">Pourquoi</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>On ne change pas le critère après coup.</strong></td><td style="text-align:left;">Sinon, tous les outils finissent par réussir.</td></tr><tr><td style="text-align:left;"><strong>Si le scénario doit changer, on le note.</strong></td><td style="text-align:left;">« Fonction introuvable : on a fait E4 avec 3 places au lieu de 5. » Le lecteur doit le savoir.</td></tr><tr><td style="text-align:left;"><strong>Le chronomètre part</strong> quand la personne touche à l&#39;écran, <strong>et s&#39;arrête</strong> quand le résultat est visible.</td><td style="text-align:left;">Mêmes règles pour chaque outil.</td></tr><tr><td style="text-align:left;"><strong>La personne qui joue Mélanie n&#39;est pas aidée.</strong></td><td style="text-align:left;">Si elle demande de l&#39;aide, on note « aide demandée » et on continue. C&#39;est une mesure, pas un échec de l&#39;équipe.</td></tr><tr><td style="text-align:left;"><strong>Données inventées seulement.</strong></td><td style="text-align:left;">Aucun vrai nom, aucune vraie carte, aucune vraie information de santé (Loi 25).</td></tr></tbody></table><hr><h2 id="activite-1" tabindex="-1">Activité 1 — Constat, affirmation non appuyée ou recommandation ? <a class="header-anchor" href="#activite-1" aria-label="Permalink to &quot;Activité 1 — Constat, affirmation non appuyée ou recommandation ? {#activite-1}&quot;">​</a></h2><p>Dans l&#39;évaluation 1, la section 6 décrit les possibilités techniques. Chaque phrase doit être un <strong>constat appuyé</strong> : sur le mandat, sur une source datée ou sur <strong>vos essais</strong>. Deux sortes de phrases s&#39;y glissent sans qu&#39;on s&#39;en rende compte.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Sorte de phrase</th><th style="text-align:left;">Ce qui la trahit</th><th style="text-align:left;">Ce qu&#39;on en fait</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Constat appuyé</strong></td><td style="text-align:left;">Une mesure, une date, une source, un renvoi à un essai</td><td style="text-align:left;">On la garde</td></tr><tr><td style="text-align:left;"><strong>Affirmation non appuyée</strong></td><td style="text-align:left;"><em>facile</em>, <em>rapide</em>, <em>complet</em>, <em>performant</em>, <em>tout le monde</em>, <em>risque de</em>… sans preuve</td><td style="text-align:left;">On la remplace par ce qu&#39;on a mesuré ou lu</td></tr><tr><td style="text-align:left;"><strong>Recommandation</strong></td><td style="text-align:left;"><em>nous recommandons</em>, <em>il faudrait</em>, <em>devrait</em>, <em>le meilleur choix</em>, <em>à privilégier</em>, <em>idéalement</em></td><td style="text-align:left;">On la retire de l&#39;évaluation 1 et on garde le fait qui se cache derrière</td></tr></tbody></table><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Consigne (15 min, en équipe, puis retour en grand groupe)</strong><br> Les onze phrases ci-dessous viennent du brouillon d&#39;une équipe fictive. Les outils sont inventés. <ol class="list-decimal pl-5"><li>Classez chaque phrase. La réponse s&#39;affiche après votre choix.</li><li>Pour chaque phrase qui n&#39;est pas un constat, écrivez votre réécriture <strong>avant</strong> de regarder celle qu&#39;on propose. Inventez la mesure ou la source au besoin.</li></ol></div>',28)),a(n),e[1]||(e[1]=t('<p><strong>Ce qu&#39;il faut retenir :</strong> derrière presque chaque recommandation, il y a un fait utile. Le travail de l&#39;évaluation 1, c&#39;est de <strong>trouver ce fait et de le montrer</strong>, pour que Mélanie puisse décider. L&#39;évaluation 2 dira ce que vous lui conseillez.</p><hr><h2 id="comparer-sans-recommander" tabindex="-1">Comparer sans recommander <a class="header-anchor" href="#comparer-sans-recommander" aria-label="Permalink to &quot;Comparer sans recommander&quot;">​</a></h2><p>À la fin du lab, vous aurez des résultats pour deux ou trois outils. L&#39;évaluation 1 demande de les présenter dans un <strong>tableau de comparaison</strong>, sur les mêmes critères, sans désigner de gagnant.</p><h3 id="les-familles-de-solutions" tabindex="-1">Les familles de solutions <a class="header-anchor" href="#les-familles-de-solutions" aria-label="Permalink to &quot;Les familles de solutions&quot;">​</a></h3><p>Avant de comparer des outils, situez-les. Pour presque toutes les questions, il existe trois grandes façons de répondre au besoin.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Famille</th><th style="text-align:left;">Exemple pour Q1 (réservation)</th><th style="text-align:left;">Ce qu&#39;on gagne</th><th style="text-align:left;">Ce qu&#39;on risque</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Un service spécialisé</strong>, payé par abonnement</td><td style="text-align:left;">Un logiciel de réservation pour les entreprises d&#39;activités</td><td style="text-align:left;">Des fonctions pensées pour le métier, mises à jour par le fournisseur</td><td style="text-align:left;">Un outil de plus à payer, à apprendre et à relier au site</td></tr><tr><td style="text-align:left;"><strong>Une fonction de la plateforme du site</strong> (module, extension)</td><td style="text-align:left;">Le module de réservation du constructeur de site</td><td style="text-align:left;">Tout au même endroit, une seule facture</td><td style="text-align:left;">Des fonctions souvent plus simples : capacité par départ, synchronisation avec Viator…</td></tr><tr><td style="text-align:left;"><strong>Un développement sur mesure</strong></td><td style="text-align:left;">Un système de réservation programmé pour le client</td><td style="text-align:left;">Exactement ce que le client veut</td><td style="text-align:left;">Le coût, le délai, et la dépendance envers celui qui l&#39;a programmé</td></tr></tbody></table><p>Dans le rapport, nommez la famille de chaque outil. Une équipe qui n&#39;a essayé que des outils de la même famille doit au moins <strong>décrire</strong> les autres familles.</p><h3 id="les-criteres-du-tableau-de-comparaison" tabindex="-1">Les critères du tableau de comparaison <a class="header-anchor" href="#les-criteres-du-tableau-de-comparaison" aria-label="Permalink to &quot;Les critères du tableau de comparaison&quot;">​</a></h3><p>Ce sont les lignes du tableau demandé dans l&#39;évaluation 1. Chaque case se remplit avec un <strong>constat</strong> : une mesure de vos essais ou une information d&#39;une source citée.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Critère</th><th style="text-align:left;">La question à se poser</th><th style="text-align:left;">Où trouver la réponse</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Ce que l&#39;outil fait</strong></td><td style="text-align:left;">Quels besoins essentiels du Lab 03 sont couverts ? Lesquels ne le sont pas ?</td><td style="text-align:left;">Vos essais d&#39;abord, la documentation ensuite</td></tr><tr><td style="text-align:left;"><strong>Le modèle de prix et le coût sur trois ans</strong></td><td style="text-align:left;">Combien, au total, pour les trois premières années, en dollars canadiens ?</td><td style="text-align:left;">La page de prix (datée), et votre calcul avec ses hypothèses</td></tr><tr><td style="text-align:left;"><strong>Le temps pour apprendre</strong></td><td style="text-align:left;">Combien de temps avant que Mélanie puisse faire seule une tâche courante ?</td><td style="text-align:left;">L&#39;essai joué par le membre qui ne connaît pas l&#39;outil; l&#39;aide offerte en français</td></tr><tr><td style="text-align:left;"><strong>La facilité d&#39;en changer</strong></td><td style="text-align:left;">Si l&#39;entreprise veut quitter l&#39;outil dans trois ans, que peut-elle emporter ?</td><td style="text-align:left;">L&#39;essai de sortie : export, format, fermeture du compte; les conditions d&#39;utilisation</td></tr><tr><td style="text-align:left;"><strong>Les signes de pérennité</strong></td><td style="text-align:left;">Qu&#39;est-ce qui indique que l&#39;outil existera encore dans cinq ans ?</td><td style="text-align:left;">Le journal des modifications, l&#39;historique de l&#39;entreprise, les témoignages récents</td></tr></tbody></table><hr><h2 id="a-faire-a-la-maison" tabindex="-1">À faire à la maison <a class="header-anchor" href="#a-faire-a-la-maison" aria-label="Permalink to &quot;À faire à la maison {#a-faire-a-la-maison}&quot;">​</a></h2><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Pour compléter votre tableau de comparaison</strong><br> Trois lignes du tableau demandent plus que vos essais : la <strong>facilité d&#39;en changer</strong>, les <strong>signes de pérennité</strong> et le <strong>coût sur trois ans</strong>. Lisez les trois sections ci-dessous, faites l&#39;activité 2, puis complétez ces lignes dans la fiche du Lab 04 avant de la déposer. </div><h3 id="lire-le-verrouillage-ou-la-facilite-d-en-changer" tabindex="-1">Lire : le verrouillage, ou la facilité d&#39;en changer <a class="header-anchor" href="#lire-le-verrouillage-ou-la-facilite-d-en-changer" aria-label="Permalink to &quot;Lire : le verrouillage, ou la facilité d&#39;en changer&quot;">​</a></h3><p>On parle de <strong>verrouillage</strong> (en anglais, <em>lock-in</em>) quand il coûte si cher de quitter un outil qu&#39;on reste, même s&#39;il ne convient plus. Le client en vit déjà un : le site actuel est sur Wix, au nom du neveu, et personne ne sait le modifier.</p><p>Ce qui verrouille le plus souvent :</p><ul><li><strong>Les données qu&#39;on ne peut pas exporter</strong>, ou seulement dans un format que personne d&#39;autre ne lit. Une liste de réservations en CSV ou en Excel se réutilise; un PDF par client, beaucoup moins.</li><li><strong>Le contenu qui ne sort pas de la plateforme.</strong> Un site fait sur un constructeur ne se transporte généralement pas tel quel chez un autre : il faut le refaire. Le <a href="https://support.wix.com/en/article/exporting-or-embedding-your-wix-site-elsewhere" target="_blank" rel="noreferrer">centre d&#39;aide de Wix</a> l&#39;indique clairement : un site Wix ne peut pas être hébergé ailleurs. Le nom de domaine, lui, peut changer de fournisseur.</li><li><strong>Les comptes au nom d&#39;une personne</strong> plutôt que de l&#39;entreprise.</li><li><strong>Les contrats</strong> : engagement de 12 mois, frais de résiliation, renouvellement automatique.</li></ul><h3 id="lire-les-signes-de-perennite" tabindex="-1">Lire : les signes de pérennité <a class="header-anchor" href="#lire-les-signes-de-perennite" aria-label="Permalink to &quot;Lire : les signes de pérennité&quot;">​</a></h3><p>Personne ne peut prédire qu&#39;un outil existera dans cinq ans. On peut toutefois <strong>observer des signes</strong> et les rapporter, avec leur source. Aucun signe ne suffit seul.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Plutôt rassurant</th><th style="text-align:left;">Plutôt inquiétant</th></tr></thead><tbody><tr><td style="text-align:left;">Un journal des modifications avec des nouveautés récentes</td><td style="text-align:left;">Aucune nouveauté depuis plus d&#39;un an</td></tr><tr><td style="text-align:left;">Une application mobile mise à jour régulièrement</td><td style="text-align:left;">Une application mal notée et pas mise à jour depuis longtemps</td></tr><tr><td style="text-align:left;">Une entreprise qui existe depuis plusieurs années, des clients nommés</td><td style="text-align:left;">Aucun nom, aucune adresse, aucune date sur le site</td></tr><tr><td style="text-align:left;">Une page d&#39;état du service, qui montre l&#39;historique des pannes</td><td style="text-align:left;">Des témoignages récents de pannes sans réponse du support</td></tr><tr><td style="text-align:left;">Des prix publics et des conditions claires</td><td style="text-align:left;">L&#39;annonce de la fin d&#39;une fonction ou d&#39;un forfait</td></tr></tbody></table><div class="bg-slate-50 border border-slate-200 text-slate-800 rounded-lg p-4 mb-5"><strong>Un rachat : bon ou mauvais signe ?</strong><br> Quand une grande entreprise achète un outil, il a plus de moyens… mais ses prix et ses priorités peuvent changer. Exemple : le logiciel de réservation Bókun appartient à Tripadvisor, qui possède aussi Viator. Pour Aventure Saint-Maurice, est-ce un avantage ou un risque ? Les deux : c&#39;est exactement le genre de nuance à <strong>décrire</strong> dans le rapport, sans trancher. </div><h3 id="le-cout-sur-trois-ans" tabindex="-1">Le coût sur trois ans <a class="header-anchor" href="#le-cout-sur-trois-ans" aria-label="Permalink to &quot;Le coût sur trois ans&quot;">​</a></h3><p>Le prix affiché d&#39;un outil, c&#39;est rarement ce qu&#39;il coûte vraiment. L&#39;évaluation 1 demande une <strong>estimation sur trois ans</strong>, parce que la première année est souvent trompeuse.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Ce qui change d&#39;une année à l&#39;autre</th><th style="text-align:left;">Exemple</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Les frais payés une seule fois</strong></td><td style="text-align:left;">Mise en place, configuration, importation des données, formation</td></tr><tr><td style="text-align:left;"><strong>Les prix de lancement</strong></td><td style="text-align:left;">« 25 $ par mois la première année », puis le prix régulier</td></tr><tr><td style="text-align:left;"><strong>Les frais qui suivent l&#39;usage</strong></td><td style="text-align:left;">Commission par réservation, prix par décharge signée, prix au visionnement d&#39;une vidéo, nombre de mots traduits</td></tr><tr><td style="text-align:left;"><strong>La devise</strong></td><td style="text-align:left;">Un prix en dollars américains ou en euros, converti avec un taux qu&#39;on indique</td></tr></tbody></table><p>Montrez toujours le calcul et <strong>les hypothèses</strong> : nombre de réservations, de participants, d&#39;utilisateurs, taux de change, date de lecture des prix. Le lecteur doit pouvoir refaire votre calcul.</p><h3 id="activite-2" tabindex="-1">Activité 2 — Le coût sur trois ans <a class="header-anchor" href="#activite-2" aria-label="Permalink to &quot;Activité 2 — Le coût sur trois ans {#activite-2}&quot;">​</a></h3><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Consigne (environ 20 min, seul ou en équipe)</strong><br> Trois outils de décharge électronique <strong>fictifs</strong> pour la question Q2. Avec les hypothèses fournies, calculez pour chacun le coût de la <strong>première année</strong> et le coût <strong>total sur trois ans</strong>, en dollars canadiens. Cliquez sur « Vérifier », puis <strong>copiez vos réponses dans vos notes</strong> : on en fera un court retour au début de la séance 5, avec le retour en grand groupe sur les cinq questions. </div>',28)),a(r),e[2]||(e[2]=t('<p><strong>Ce qu&#39;il faut retenir :</strong> le classement de la première année n&#39;est pas celui de trois ans. Et le moins cher n&#39;est pas un choix : dans l&#39;évaluation 1, on présente les trois coûts côte à côte, avec ce que chaque outil fait et ne fait pas.</p><hr><h2 id="a-faire-maintenant" tabindex="-1">À faire maintenant <a class="header-anchor" href="#a-faire-maintenant" aria-label="Permalink to &quot;À faire maintenant&quot;">​</a></h2><p><a href="./../../labs/lab04-essais">Lab 04 — Les essais</a>, en équipe, jusqu&#39;à la fin de la soirée. Avant de partir, déposez ce que vous avez fait; la fiche se termine à la maison.</p><hr><h2 id="avant-la-seance-5-28-octobre" tabindex="-1">Avant la séance 5 (28 octobre) <a class="header-anchor" href="#avant-la-seance-5-28-octobre" aria-label="Permalink to &quot;Avant la séance 5 (28 octobre)&quot;">​</a></h2><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Faire l&#39;<a href="#activite-2">activité 2 — Le coût sur trois ans</a> et copier vos réponses dans vos notes</span></label></li><li><label><input type="checkbox"><span class="check-text">Compléter les lignes « coût sur trois ans », « facilité d&#39;en changer » et « signes de pérennité » du tableau de comparaison</span></label></li><li><label><input type="checkbox"><span class="check-text">Déposer la fiche du Lab 04 dans l&#39;équipe Teams du cours</span></label></li><li><label><input type="checkbox"><span class="check-text">Préparer votre <a href="./../../labs/lab04-essais#retour">présentation de 2 minutes</a> pour le retour en grand groupe du début de la séance 5</span></label></li><li><label><input type="checkbox"><span class="check-text">Terminer les essais qui n&#39;ont pas pu être faits en classe, avec les mêmes règles</span></label></li><li><label><input type="checkbox"><span class="check-text">Ranger les captures dans le dossier partagé, bien nommées : elles iront dans l&#39;annexe A</span></label></li><li><label><input type="checkbox"><span class="check-text">Rédiger le premier jet de votre question dans la section 6 du rapport, avec le tableau de comparaison</span></label></li><li><label><input type="checkbox"><span class="check-text">Commencer la recherche pour les quatre autres questions : deux outils chacune, page de prix datée et coût sur trois ans</span></label></li><li><label><input type="checkbox"><span class="check-text">Fermer les comptes d&#39;essai dont vous n&#39;avez plus besoin, ou noter leur date d&#39;expiration</span></label></li><li><label><input type="checkbox"><span class="check-text">Apporter le brouillon du rapport à la séance 5 : on travaillera l&#39;organisation et l&#39;écriture pour un client</span></label></li></ul>',7))])}const x=l(u,[["render",d]]);export{b as __pageData,x as default};
